#!/usr/bin/env node
// CI/deploy guard: detect a stale packages/daemon-standalone/vendor/mcp-server.
//
// packages/daemon-standalone ships a vendored copy of packages/mcp-server's
// build output under vendor/mcp-server, generated by:
//   npm run build -w packages/mcp-server
//   npm run bundle:vendor -w packages/daemon-standalone
//
// The vendored MCP server is a runtime artifact: the standalone package exposes
// adhdev-mcp from vendor/mcp-server/index.js and the daemon points coordinators
// at that entry. Keep the committed vendor output in sync with the source build.
//
// Sourcemap note: .map files are EXCLUDED from the drift comparison. Their
// `mappings` VLQ stream is a runtime-irrelevant debug artifact whose byte layout
// varies with the esbuild/tsup toolchain version, so a vendor re-sync on a
// different node can regenerate a byte-different .map while the .js is identical.
// That is not a source drift — a real source change always shows up in the emitted
// .js — so comparing .map files only produces cross-machine false positives.

import { execFileSync } from 'node:child_process';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const VENDOR_PATH = 'packages/daemon-standalone/vendor/mcp-server';
const isWin = process.platform === 'win32';
const npm = isWin ? 'npm.cmd' : 'npm';

function run(cmd, args) {
  console.log(`$ ${cmd} ${args.join(' ')}`);
  // Node 24 on Windows refuses to spawn .cmd/.bat shims (npm.cmd) via execFile
  // without a shell — it throws `spawnSync npm.cmd EINVAL`. Run npm through the
  // shell on win32 only; POSIX behavior is unchanged. Args here are fixed and
  // space-free, so shell word-splitting is not a concern.
  execFileSync(cmd, args, { stdio: 'inherit', cwd: root, shell: isWin });
}

run(npm, ['run', 'build', '-w', 'packages/mesh-shared']);
run(npm, ['run', 'build', '-w', 'packages/session-host-core']);
run(npm, ['run', 'build', '-w', 'packages/session-host-daemon']);
run(npm, ['run', 'build', '-w', 'packages/mcp-server']);
run(npm, ['run', 'bundle:vendor', '-w', 'packages/daemon-standalone']);

try {
  // Exclude *.map: sourcemaps are a non-reproducible debug artifact (see note above).
  execFileSync(
    'git',
    ['diff', '--exit-code', '--ignore-cr-at-eol', '--', VENDOR_PATH, `:(exclude,glob)${VENDOR_PATH}/**/*.map`],
    { stdio: 'inherit', cwd: root },
  );
} catch {
  console.error(
    `\n✗ ${VENDOR_PATH} is stale.\n` +
    `  packages/mcp-server changed but the vendored copy was not re-synced.\n` +
    `  Fix (from the cloud monorepo root): npm run bundle:vendor:all\n` +
    `       — re-syncs BOTH the daemon-cloud and daemon-standalone vendor copies.\n` +
    `  Standalone-only (inside oss): npm run bundle:vendor -w packages/daemon-standalone\n` +
    `  then commit the updated ${VENDOR_PATH}.\n`,
  );
  process.exit(1);
}

console.log(`\n✓ ${VENDOR_PATH} is in sync with packages/mcp-server build output.`);
